mapper.select:
SELECT * FROM ( SELECT t.*, ROWNUM AS rn FROM ( SELECT m.inv_code, m.inv_name, m.version, m.org_name, m.body_code, 0 AS child_count FROM ( SELECT DISTINCT bom.INVCODE AS inv_code, bom.INVNAME AS inv_name, bom.HVERSION AS version, bom.ORGNAME AS org_name, bom.BODYCODE AS body_code FROM V_BOM_OUTPUT bom INNER JOIN ( SELECT INVCODE, MAX(HVERSION) AS MAX_VERSION FROM V_BOM_OUTPUT GROUP BY INVCODE ) latest ON bom.INVCODE = latest.INVCODE AND bom.HVERSION = latest.MAX_VERSION ) m
AND (m.inv_code LIKE '%' || #{keyword} || '%' OR m.inv_name LIKE '%' || #{keyword} || '%')
ORDER BY m.inv_code ) t WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}
